import 'dart:convert';import 'dart:io';import 'package:shelf/shelf.dart';import 'package:shelf/shelf_io.dart' as io;import 'package:shelf_router/shelf_router.dart';Response out(Map<String,String> data)=>Response.ok(jsonEncode(data),headers:{'content-type':'application/json'});void main()async{final r=Router();r.get('/',(Request _)=>out({'service':'Pxxl Shelf API'}));r.get('/health',(Request _)=>out({'status':'ok'}));r.get('/api',(Request _)=>out({'message':'Hello from Dart'}));final p=int.tryParse(Platform.environment['PORT']??'8080')??8080;await io.serve(r.call,InternetAddress.anyIPv4,p);}
